UPDATE mt_power_account
SET balance = balance + #{powerAmount},
    recharge_balance = recharge_balance + #{powerAmount},
    total_recharge = total_recharge + #{powerAmount},
    version = version + 1,
    update_time = #{now}
WHERE shop_id = #{shopId}
  AND version = #{version}

UPDATE mt_power_account
SET balance = balance + #{powerAmount},
    grant_balance = grant_balance + #{powerAmount},
    total_grant = total_grant + #{powerAmount},
    version = version + 1,
    update_time = #{now}
WHERE shop_id = #{shopId}
  AND version = #{version}

UPDATE mt_power_account
SET balance = balance - #{powerAmount},
    grant_balance = grant_balance - #{grantAmount},
    recharge_balance = recharge_balance - #{rechargeAmount},
    total_consume = total_consume + #{powerAmount},
    version = version + 1,
    update_time = #{now}
WHERE shop_id = #{shopId}
  AND version = #{version}
  AND balance >= #{powerAmount}
  AND grant_balance >= #{grantAmount}
  AND recharge_balance >= #{rechargeAmount}
